&lt;/div&gt;
&lt;div class="list"&gt;&lt;/div&gt;
// 1. things you need (classes, ids)
const list = document.queryselector('.list');
const addbtn document.queryselector('.add');
// 2. user
addbtn.addeventlistener('click', () =&gt; {
 // 3. rule before changing anything
 if (list.children.length &gt;= 10) return;
 }
 4. make change
 const document.createelement('my-card');
 card.setattribute('title', 'new card');
 list.appendchild(card);
});
